import os
import datetime
import boto3

def get_metric_comparison(
    metric_name: str,
    namespace: str,
    statistic: str,
    dimensions_resource1: dict,
    dimensions_resource2: dict,
    period_seconds: int,
    start_time: datetime.datetime,
    end_time: datetime.datetime,
    region_name: str = None
) -> dict:
    """
    Compares metric values for two resources or dimension filters over the same window
    using Amazon CloudWatch Metrics.

    Args:
        metric_name: The name of the metric.
        namespace: The namespace of the metric.
        statistic: The statistic to apply to the metric data (e.g., 'Average', 'Sum', 'Maximum', 'Minimum', 'SampleCount').
        dimensions_resource1: A dictionary of dimensions for the first resource/filter.
                              Example: {'InstanceId': 'i-1234567890abcdef0'}
        dimensions_resource2: A dictionary of dimensions for the second resource/filter.
                              Example: {'InstanceId': 'i-abcdef01234567890'}
        period_seconds: The granularity, in seconds, of the returned data points.
                        For metrics with a timestamp that is greater than 2 weeks ago, you must specify a period
                        that is a multiple of 60, and you must specify a period of at least 2 weeks (1209600 seconds)
                        if you are retrieving more than 1 day of data.
        start_time: The start of the time range to retrieve metrics for.
        end_time: The end of the time range to retrieve metrics for.
        region_name: The AWS region to use. If None, it will be picked from environment variables or default AWS config.

    Returns:
        A dictionary containing the metric data for both resources,
        or None if an error occurs or no data is found.
    """

    cloudwatch = boto3.client('cloudwatch', region_name=region_name)

    metric_data_queries = [
        {
            'Id': 'm1',
            'MetricStat': {
                'Metric': {
                    'Namespace': namespace,
                    'MetricName': metric_name,
                    'Dimensions': [{'Name': k, 'Value': v} for k, v in dimensions_resource1.items()]
                },
                'Period': period_seconds,
                'Stat': statistic,
                'Unit': 'Bytes' # Specify a common unit or omit if not strictly required
            },
            'Label': f'Resource 1: {metric_name} ({statistic})'
        },
        {
            'Id': 'm2',
            'MetricStat': {
                'Metric': {
                    'Namespace': namespace,
                    'MetricName': metric_name,
                    'Dimensions': [{'Name': k, 'Value': v} for k, v in dimensions_resource2.items()]
                },
                'Period': period_seconds,
                'Stat': statistic,
                'Unit': 'Bytes' # Specify a common unit or omit if not strictly required
            },
            'Label': f'Resource 2: {metric_name} ({statistic})'
        }
    ]

    try:
        response = cloudwatch.get_metric_data(
            MetricDataQueries=metric_data_queries,
            StartTime=start_time,
            EndTime=end_time
        )

        result = {
            'resource1_data': None,
            'resource2_data': None,
            'timestamps': []
        }

        for metric_data_result in response.get('MetricDataResults', []):
            if metric_data_result['Id'] == 'm1':
                result['resource1_data'] = {
                    'values': metric_data_result.get('Values', []),
                    'timestamps': metric_data_result.get('Timestamps', [])
                }
            elif metric_data_result['Id'] == 'm2':
                result['resource2_data'] = {
                    'values': metric_data_result.get('Values', []),
                    'timestamps': metric_data_result.get('Timestamps', [])
                }

        # Consolidate timestamps if both resources have data
        if result['resource1_data'] and result['resource2_data']:
            # Assuming timestamps are consistent for the same period and start/end time
            # Pick one, or merge and sort if there's a possibility of slight differences
            result['timestamps'] = result['resource1_data']['timestamps']

        return result

    except Exception as e:
        print(f"Error retrieving CloudWatch metric data: {e}")
        return None
